>> &ctrls->frame->tile_info;
>> +    unsigned int num_tile_cols = tile_info->tile_cols;
>> +    unsigned int height = ALIGN(ctrls->frame->frame_height_minus_1 + 
>> 1, 64);
>> +    unsigned int height_in_sb = height / 64;
>> +    unsigned int stripe_num = ((height + 8) + 63) / 64;
