>> +
>> +    size = ALIGN(height * 12 * ctx->bit_depth / 8, 128) * 
>> num_tile_cols;
>> +    av1_dec->db_data_col.cpu = dma_alloc_coherent(vpu->dev, size,
>> +                              &av1_dec->db_data_col.dma,
>> +                              GFP_KERNEL);
